modules[S(132)] = function()
local function dumpInstance(instance, log, indent)
    indent = indent or S(16)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(43) .. child.Name .. S(124)
        if child:IsA(S(5)) then
            line = line .. string.format(
                S(171),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(183)) then
            line = line .. string.format(S(105), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(85)) or child:IsA(S(1)) then
            line = line .. S(23)
        end
        log(line)
        dumpInstance(child, log, indent .. S(50))
    end
end
return dumpInstance
end
